//! Publish the committed C header to the drivers' build scripts.
//!
//! `include/pie_forward.h` is generated by `cargo run -p model-cbindgen` out
//! of this crate's `#[repr(C)]` FFI surface and committed, so a standalone
//! CMake configure works without a cargo build. A driver's build script reads
//! `DEP_PIE_FORWARD_INCLUDE` and puts it on the C++ include path — the same
//! handoff `model-loader-capi` uses for `pie_loader.h`.
//!
//! No compilation happens here, and no fingerprinting either. The tracer's
//! content hash stays in `model-compiler`'s build script, because the tracer
//! is what it fingerprints; `ffi::compiler_version()` reads it back through
//! `model_compiler::compiler_version()` rather than recomputing it over a
//! tree that also holds chat templates.

fn main() {
    let include = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("include");
    println!("cargo:include={}", include.display());
    println!("cargo:rerun-if-changed=include");
}
